import time
from collections import deque
from typing import Dict, List, Tuple

class AdaptiveFanoutManager:
    def __init__(self, min_fanout: int = 3, max_fanout: int = 15, default_fanout: int = 6, window_size: int = 50):
        self.min_fanout = min_fanout
        self.max_fanout = max_fanout
        self.default_fanout = default_fanout
        self.window_size = window_size
        self.latencies: deque = deque(maxlen=window_size)
        self.drop_rates: deque = deque(maxlen=window_size)

    def record_metrics(self, latency_ms: float, drop_rate: float):
        self.latencies.append(latency_ms)
        self.drop_rates.append(drop_rate)

    def compute_fanout(self) -> int:
        if not self.latencies or not self.drop_rates:
            return self.default_fanout

        avg_latency = sum(self.latencies) / len(self.latencies)
        avg_drop = sum(self.drop_rates) / len(self.drop_rates)

        fanout = self.default_fanout
        if avg_latency > 250.0 or avg_drop > 0.15:
            fanout += 2
        elif avg_latency < 80.0 and avg_drop < 0.02:
            fanout -= 1

        return max(self.min_fanout, min(self.max_fanout, fanout))

    def get_adaptive_targets(self, peers: List[str]) -> List[str]:
        target_count = self.compute_fanout()
        return peers[:target_count]

from typing import List
from gossipmesh.p2p.adaptive_fanout import AdaptiveFanoutManager

class GossipTransport:
    def __init__(self, min_fanout: int = 3, max_fanout: int = 15, default_fanout: int = 6):
        self.fanout_manager = AdaptiveFanoutManager(min_fanout=min_fanout, max_fanout=max_fanout, default_fanout=default_fanout)

    def record_peer_telemetry(self, latency_ms: float, drop_rate: float):
        self.fanout_manager.record_metrics(latency_ms, drop_rate)

    def select_gossip_peers(self, all_peers: List[str]) -> List[str]:
        return self.fanout_manager.get_adaptive_targets(all_peers)

import unittest
from gossipmesh.p2p.adaptive_fanout import AdaptiveFanoutManager
from gossipmesh.p2p.transport import GossipTransport

class TestAdaptiveFanout(unittest.TestCase):
    def test_default_fanout(self):
        manager = AdaptiveFanoutManager(default_fanout=5)
        self.assertEqual(manager.compute_fanout(), 5)

    def test_high_latency_adaptation(self):
        manager = AdaptiveFanoutManager(default_fanout=5, max_fanout=10)
        for _ in range(10):
            manager.record_metrics(latency_ms=300.0, drop_rate=0.0)
        self.assertGreater(manager.compute_fanout(), 5)

    def test_low_latency_adaptation(self):
        manager = AdaptiveFanoutManager(default_fanout=5, min_fanout=2)
        for _ in range(10):
            manager.record_metrics(latency_ms=50.0, drop_rate=0.0)
        self.assertLess(manager.compute_fanout(), 5)

    def test_transport_integration(self):
        transport = GossipTransport(default_fanout=3, max_fanout=10)
        peers = [f"peer_{i}" for i in range(10)]
        targets = transport.select_gossip_peers(peers)
        self.assertEqual(len(targets), 3)

if __name__ == '__main__':
    unittest.main()
